message.content:
{
  "description": "The creature is shown in right-facing profile standing on a small patch of ground with stones and sparse grass. It has the overall body shape, dense shaggy fur, and proportions of a large bear, with four thick legs and a short tail, but its dorsal surface from behind the neck to above the hindquarters is covered by a large, glossy, dark reddish-brown segmented exoskeleton, and a single long, curved, ridged horn rises from the center of its forehead. The fur is medium to dark brown with a lighter tan area on the muzzle, lower cheek, and side of the chest. The shell is highly reflective with distinct transverse sutures and a larger shield over the shoulders.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like, covered in dense brown fur with a lighter tan muzzle and lower cheek, a large black nose at the tip, small brown eyes on the sides, and a closed mouth",
      "where": "at the anterior end of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "one prominent, glossy, dark brown to black horn with transverse ridges/segments, tapering to a pointed tip and curving upward and backward",
      "where": "arising from the midline of the forehead between and slightly in front of the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, densely furred ears, same brown as the head fur",
      "where": "on the top of the head, one on each side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick, heavily furred, columnar legs with shaggy brown fur, darker on the lower portions",
      "where": "two forelegs under the chest/shoulder and two hindlegs under the hips, supporting the body vertically"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with visible long, curved, dark claws on the toes",
      "where": "at the distal ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "very small, short, rounded nub of brown fur",
      "where": "at the posterior end of the body, just below the rear edge of the shell, on the left side of the rump as viewed"
    },
    {
      "part": "shell",
      "looks_like": "large, glossy, dome-shaped exoskeleton, dark reddish-brown with blackish shading, covering the back",
      "where": "on the dorsal surface extending from just behind the neck to above the hindquarters, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "overlapping transverse plates with dark sutures forming the main dome, a larger anterior shield over the shoulders with two small pointed projections on its upper edge and a row of small circular pits along its lower edge, and a lower fringe of smaller flap-like plates each with an oval hole",
      "where": "the transverse plates form the central and posterior dome of the shell, the larger shield covers the shoulder area, and the fringed plates run along the ventral margin of the shell on the side of the body"
    },
    {
      "part": "markings",
      "looks_like": "a patch of lighter cream-tan fur contrasting with the surrounding dark brown fur, no spots, stripes, or feather/scale patterns on the fur itself",
      "where": "on the side of the chest and flank, visible between the foreleg and hindleg and on the lower neck"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "rhinoceros beetle", "pill bug"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
